// Symbol.iterator — make object iterable:
class NumberRange {
  constructor(start, end) { this.start = start; this.end = end; }
  [Symbol.iterator]() {
    let cur = this.start, end = this.end;
    return { next: () => cur <= end
      ? { value: cur++, done: false }
      : { done: true } };
  }
}
[...new NumberRange(1, 3)]; // [1, 2, 3]

// Symbol.toPrimitive — custom coercion:
const money = {
  amount: 100, currency: 'USD',
  [Symbol.toPrimitive](hint) {
    if (hint === 'number') return this.amount;
    if (hint === 'string') return this.amount + ' ' + this.currency;
    return this.amount;
  }
};
+money;      // 100
`${money}`;  // "100 USD"
money + 5;   // 105

// Symbol.hasInstance — customise instanceof:
class Even {
  static [Symbol.hasInstance](num) { return num % 2 === 0; }
}
2 instanceof Even;  // true
3 instanceof Even;  // false

// Custom iterable using Symbol.iterator:
const range = {
  from: 1, to: 5,
  [Symbol.iterator]() {
    let current = this.from;
    const last = this.to;
    return {
      next() {
        return current <= last
          ? { value: current++, done: false }
          : { value: undefined, done: true };
      }
    };
  }
};

for (const n of range) console.log(n); // 1 2 3 4 5

